def copy_file(src, dst):
    """Sound files: a hard link (no mutant changes one; 1351 files per copy). Else a normal copy."""
    if str(src).endswith(".ogg"):
        try:
            os.link(src, dst)
            return dst
        except OSError:
            pass
    return shutil.copy2(src, dst)


HANG_S = 300   # one "all" run takes well under a minute; past this the mutant hangs the tests = killed


def run():
    try:
        return subprocess.run([sys.executable, "-I", str(ROOT / "tools" / "lua.py"), "all", str(WORK)],
                              capture_output=True, text=True, timeout=HANG_S).returncode
    except subprocess.TimeoutExpired:
        print(f"hang (over {HANG_S} s):", flush=True, end=" ")
        return 124


def src_of(file):
    """The source file of a mutant: the addon, or the dev folder (DEV prefix)."""
    return DEV_SRC / file[len(DEV):] if file.startswith(DEV) else SRC / file


def main():
    killed = 0
    for name, file, old, new in MUTANTS:
        if WORK.parent.exists():
            shutil.rmtree(WORK.parent)
        shutil.copytree(SRC, WORK, copy_function=copy_file)
        if DEV_SRC.exists():
            shutil.copytree(DEV_SRC, WORK.parent / "Spoken_Wind_Dev")
        elif file.startswith(DEV):
            print(f"skip (no dev folder): {name}")
            killed += 1
            continue
        p = WORK / file
        s = p.read_text(encoding="utf-8")
        if old not in s:
            print(f"BAD MUTANT (text not found): {name}")
            return 1
        p.write_text(s.replace(old, new, 1), encoding="utf-8")
        rc = run()
        killed += rc != 0
        print(f"{'killed' if rc else 'SURVIVED'}  {name}")
    shutil.rmtree(WORK.parent)
    print(f"{killed}/{len(MUTANTS)} killed")
    return 0 if killed == len(MUTANTS) else 1


if __name__ == "__main__":
    sys.exit(main())
